export async function handleQuote(req: QuoteRequest): Promise<Quote> {
  const useNew = await flags.enabled('quotes.v2', {
    // Sticky per customer: a customer must not see two different quoting
    // engines on consecutive requests.
    key: req.customerId,
    percentage: 10,
  });

  if (!useNew) return legacyQuote(req);

  const quote = await newQuote(req);

  // Shadow-compare a sample. The old path still runs, its result is not
  // returned, and any difference is logged. This is how a rounding rule
  // nobody documented gets found before a customer finds it.
  if (sample(0.05)) {
    void (async () => {
      try {
        const legacy = await legacyQuote(req);
        if (legacy.totalMinor !== quote.totalMinor) {
          log.warn('quote.mismatch', {
            customerId: req.customerId,
            legacy: legacy.totalMinor,
            next: quote.totalMinor,
            delta: quote.totalMinor - legacy.totalMinor,
          });
        }
      } catch (err) {
        // The shadow path must never affect the response the user gets.
        log.warn('quote.shadow_failed', { err });
      }
    })();
  }

  return quote;
}
